import { afterEach, describe, expect, it } from 'vitest'
import type { ToolDefinition } from '@deepseek-ai/dsh-tools'
import type { AgentTeamProjectRef } from '@contexera/dsh-agent-team/types'
import { cleanups, realHarness, requestId } from '../../agent-team/tests/helpers/member-harness.ts'
import { teamTools } from './render-text.ts'

/**
 * Execution-level addressing tests over the real Host and live Member
 * Sessions. The Host is seeded through its public API; the tool definitions
 * are the source under test. No Host result or refusal is mocked.
 */

afterEach(async () => {
  await Promise.all(cleanups.splice(0).map(cleanup => cleanup()))
})

type Harness = Awaited<ReturnType<typeof realHarness>>
type Member = { readonly agent: NonNullable<ReturnType<Harness['ctx']['agents']['get']>> }

async function addMember(ctx: Harness['ctx'], workspaceId: Harness['workspaceId'], handle: string, projectRef: AgentTeamProjectRef): Promise<Member> {
  const added = await ctx.agentTeam.addMember({ requestId: requestId(`add-${handle}`), workspaceId, handle, description: '', presetId: 'team-member', projectRefs: [projectRef] })
  const agent = ctx.agents.get(added.status.member.sessionId)
  if (agent === undefined) throw new Error(`Member ${handle} did not get a live Agent`)
  return { agent }
}

async function boot() {
  const { ctx, workspaceId } = await realHarness()
  const project = await ctx.agentTeam.createProject({ requestId: requestId('project'), workspaceId, name: 'alpha', description: '', memberIds: [] })
  const projectRef = project.project.projectRef
  const peer = await addMember(ctx, workspaceId, 'peer', projectRef)
  const other = await addMember(ctx, workspaceId, 'other', projectRef)
  const first = await ctx.agentTeam.startThread({ requestId: requestId('first-task'), workspaceId, projectRef, kind: 'task', body: 'First task' })
  const second = await ctx.agentTeam.startThread({ requestId: requestId('second-task'), workspaceId, projectRef, kind: 'task', body: 'Second task' })
  if (first.task === undefined || second.task === undefined) throw new Error('the seeded Threads did not carry Tasks')
  return { ctx, workspaceId, projectRef, peer, other, first, second,
    firstTask: first.task.taskRef, secondTask: second.task.taskRef, firstThread: first.thread.threadRef }
}

function call(name: string, args: Record<string, unknown>, agent: Member['agent']): Promise<unknown> {
  const tool: ToolDefinition | undefined = teamTools().get(name)
  if (tool === undefined) throw new Error(`tool ${name} is not registered`)
  return tool.execute(args, { agent, callId: `call:${crypto.randomUUID()}`, signal: new AbortController().signal } as never)
}

describe('Thread and Main addressing over the real Host', () => {
  it('accepts the same Thread through both refs and rejects refs from different Threads', async () => {
    const team = await boot()

    const status = await call('team_attention', { action: 'status', threadRef: team.firstThread, taskRef: team.firstTask }, team.peer.agent)
    expect(status).toMatchObject({ threadRef: team.firstThread })

    const read = await call('team_thread', { action: 'read', threadRef: team.firstThread, taskRef: team.firstTask }, team.peer.agent)
    expect(read).toMatchObject({ threadRef: team.firstThread })

    await expect(call('team_attention', { action: 'status', threadRef: team.firstThread, taskRef: team.secondTask }, team.peer.agent))
      .rejects.toThrow(/does not belong/)
    await expect(call('team_thread', { action: 'read', threadRef: team.firstThread, taskRef: team.secondTask }, team.peer.agent))
      .rejects.toThrow(/does not belong/)
  })

  it('reads a Thread Message with threadRef and ignores an extra taskRef; projectRef reads the Main stream', async () => {
    const team = await boot()

    const threadMessage = await call('team_thread', { action: 'message', threadRef: team.firstThread, taskRef: team.firstTask, messageRef: team.first.message.messageRef }, team.peer.agent)
    expect(threadMessage).toMatchObject({ kind: 'message', message: { messageRef: team.first.message.messageRef } })

    const posted = await team.ctx.agentTeam.postMainMessage({ requestId: requestId('main-post'), workspaceId: team.workspaceId, projectRef: team.projectRef, body: 'Main hello' })
    if (posted.kind !== 'committed') throw new Error(`Main stream post was refused: ${posted.kind}`)
    const mainMessage = await call('team_thread', { action: 'message', projectRef: team.projectRef, messageRef: posted.message.messageRef }, team.peer.agent)
    expect(mainMessage).toMatchObject({ kind: 'message', message: { messageRef: posted.message.messageRef, body: 'Main hello' } })
  })

  it('refuses unfollow only for the caller\'s own active Claim', async () => {
    const team = await boot()
    const peerRead = await team.ctx.agentTeam.readThreadForAgent(team.peer.agent, { requestId: requestId('peer-read'), workspaceId: team.workspaceId, threadRef: team.firstThread })
    const claimed = await team.ctx.agentTeam.changeClaimForAgent(team.peer.agent, { requestId: requestId('peer-claim'), workspaceId: team.workspaceId,
      taskRef: team.firstTask, action: 'claim', direction: 'peer owns the first task', baseRevision: peerRead.thread.revision })
    expect(claimed.kind).toBe('committed')
    await team.ctx.agentTeam.changeAttentionForAgent(team.other.agent, { requestId: requestId('other-follow'), workspaceId: team.workspaceId, threadRef: team.firstThread, action: 'follow' })

    await expect(call('team_attention', { action: 'unfollow', threadRef: team.firstThread }, team.peer.agent))
      .rejects.toThrow(/active Claim.*finish the work or release the Claim first/)
    expect(team.ctx.agentTeam.attentionStatusForAgent(team.peer.agent, { workspaceId: team.workspaceId, threadRef: team.firstThread }).attention).toBeDefined()

    const other = await call('team_attention', { action: 'unfollow', threadRef: team.firstThread }, team.other.agent)
    expect(other).toMatchObject({ following: false, threadRef: team.firstThread })
    expect(team.ctx.agentTeam.attentionStatusForAgent(team.other.agent, { workspaceId: team.workspaceId, threadRef: team.firstThread }).attention).toBeUndefined()
  })
})

import { readFile } from 'node:fs/promises'
import { resolve } from 'node:path'
import { Session, SessionId, deriveEventMessage, type SessionEvent, type SessionHeader } from '@deepseek-ai/dsh-session'
import type { Message, RequestMessage } from '@deepseek-ai/dsh-llm'

interface Snapshot {
  stage: string
  sessionId: string
  header: SessionHeader
  events: SessionEvent[]
  requests: { messages: RequestMessage[]; tools?: unknown }[]
}

function textUnits(message: Message | RequestMessage): number {
  return message.content.reduce((sum, part) => sum + (part.type === 'text' ? part.text.length : 0), 0)
}

function category(message: Message): string {
  if (message.role !== 'user') return message.role
  const source = message.source as Record<string, unknown>
  const tag = source['memberContext'] as { category?: string; variant?: string } | undefined
  if (tag?.category !== undefined) return `member-context:${tag.category}${tag.variant === undefined ? '' : `:${tag.variant}`}`
  return `${source['kind']}:${source['form'] ?? 'message'}`
}

function measure(snapshot: Snapshot) {
  const session = Session.create(SessionId(snapshot.sessionId), snapshot.events, snapshot.header)
  const outputs: { category: string; textCodeUnits: number }[] = []
  const calls = new Map<string, string>()
  let partBindings = 0
  let wholeMessageBindings = 0
  for (const event of snapshot.events) {
    if (event.type === 'tool/call') {
      const args = JSON.parse(event.data.arguments) as { action?: string }
      calls.set(event.data.callId, `${event.data.name}:${args.action ?? '-'}`)
    }
    const message = deriveEventMessage(event)
    if (message === null) continue
    const label = message.role === 'tool' ? calls.get(message.toolCallId) ?? 'tool' : category(message)
    outputs.push({ category: label, textCodeUnits: textUnits(message) })
    const binding = event.type === 'tool/result'
      ? (event.data.meta as { teamFacts?: { messages?: { start?: number }[] } } | undefined)?.teamFacts
      : message.role === 'user' ? (message.source as { teamFacts?: { messages?: { start?: number }[] } }).teamFacts : undefined
    for (const item of binding?.messages ?? []) {
      if (item.start === undefined) wholeMessageBindings += 1
      else partBindings += 1
    }
  }
  const categories: Record<string, { messages: number; textCodeUnits: number }> = {}
  for (const output of outputs) {
    const count = categories[output.category] ??= { messages: 0, textCodeUnits: 0 }
    count.messages += 1
    count.textCodeUnits += output.textCodeUnits
  }
  const surface = session.deriveMessages()
  return {
    stage: snapshot.stage,
    sessionId: snapshot.sessionId,
    cumulativeLog: {
      eventCount: snapshot.events.length,
      textCodeUnits: outputs.reduce((sum, item) => sum + item.textCodeUnits, 0),
      categories,
      wholeMessageBindings,
      partBindings,
    },
    currentSurface: {
      messageCount: surface.length,
      textCodeUnits: surface.reduce((sum, message) => sum + textUnits(message), 0),
    },
    requests: snapshot.requests.map((request, index) => ({
      index,
      textCodeUnits: request.messages.reduce((sum, message) => sum + textUnits(message), 0),
      messageJsonCodeUnits: JSON.stringify(request.messages).length,
      toolSchemaJsonCodeUnits: JSON.stringify(request.tools ?? []).length,
    })),
  }
}

const paths = process.argv.slice(2)
if (paths.length === 0) throw new Error('Pass explicit synthetic snapshot JSON paths; no personal Session directory is scanned.')
const snapshots: Snapshot[] = []
for (const path of paths) {
  const input = JSON.parse(await readFile(resolve(path), 'utf8')) as { format?: string; snapshots?: Snapshot[] }
  if (input.format !== 'team-context-snapshots-v1' || !Array.isArray(input.snapshots)) {
    throw new Error(`${path}: expected team-context-snapshots-v1 from the deterministic scenario; raw persistence logs are not this format`)
  }
  snapshots.push(...input.snapshots)
}
const latest = new Map<string, Snapshot>()
for (const snapshot of snapshots) latest.set(snapshot.sessionId, snapshot)
console.log(JSON.stringify({
  inputFiles: paths.length,
  sessions: latest.size,
  snapshots: snapshots.map(measure),
  finalSessions: [...latest.values()].map(snapshot => ({ sessionId: snapshot.sessionId, finalStage: snapshot.stage })),
  note: 'UTF-16 code units, not tokens or cost. Each snapshot is cumulative within its own Session; never sum successive snapshots. Requests are recorded GenerateOptions from the realHarness test preset, which omits the shipped persona prefix; they are not production request totals or provider wire payloads. Part bindings count emitted segments, not unique or currently visible content. Input files are synthetic exports, not counts of Session persistence files.',
}, null, 2))

import { createRequire } from 'node:module'
import { readFile, readdir } from 'node:fs/promises'
import { join, resolve } from 'node:path'
import { pathToFileURL } from 'node:url'
import { describe, expect, it } from 'vitest'
import { Context } from '@deepseek-ai/cordis'
import { applyEntryPatches } from '@deepseek-ai/cordis-plugin-include'
import { loadOverlayPatches } from '@deepseek-ai/dsh-app-boot'
import * as Persona from '@deepseek-ai/dsh-persona'
import { createScope } from '@deepseek-ai/dsh-scope'
import SystemPrompt, { renderPrompt } from '@deepseek-ai/dsh-system-prompt'
import { HUMAN_PROFILE_SETTINGS_SCHEMA } from '../src/human-profile.ts'
import { HUMAN_PROFILE_SETTINGS_NAMESPACE } from '../src/human-settings.ts'
import { TEAM_HOST_ROW_SETTINGS_SCHEMA } from '../src/index.ts'
import { dshPeerRanges } from '../../../scripts/dsh-peers.mjs'

const root = resolve(import.meta.dirname, '../../../')

// The shipped bundle patch stack resolves against the SAME harness checkout
// the rest of the build uses (env override for certification rounds, then the
// .generated-harness marker, then the daily sibling) — never a hardcoded
// name, or a compat round would sweep the daily checkout's rows instead of
// the candidate's.
async function shippedHarnessName(): Promise<string> {
  const marker = resolve(root, '.generated-harness')
  try {
    return process.env.DSH_HARNESS_DIR?.trim() || (await readFile(marker, 'utf8')).trim() || 'deepseek-harness'
  } catch {
    return process.env.DSH_HARNESS_DIR?.trim() || 'deepseek-harness'
  }
}

// The persona is injected into every Member turn and ships to every user, so its
// size is a reviewed budget rather than a measurement: raising this number is a
// deliberate act in the same change that edits the text. Silent accretion is what
// this test exists to stop. The 2026-09-14 markdown rewrite (communication
// discipline, Decision-needed template removed, progress nudges deleted in the
// same change) moved the reviewed size up once, with headroom for wording that
// earns its characters. The 2026-09-15 Thread entry/re-entry rule moved it up
// again on the operator's instruction, to stop leaving every wording-only
// improvement squeezed into the last few characters. The 2026-10-29 naming
// rule moved it up again on the operator's instruction: a Member named in
// prose is not a mention, because a stray `@` inside an example or a roster
// delivers that Message and interrupts Members who need not act on it.
const PERSONA_CHARACTER_BUDGET = 15400

function teamMemberPresetText(patch: string): string {
  const start = patch.indexOf('        - id: wowyuarm-agent-team-preset-team-member')
  const end = patch.indexOf('        - id: wowyuarm-agent-team-host')
  return start >= 0 && end > start ? patch.slice(start, end) : ''
}

function personaInstructionText(preset: string): string {
  const lines = preset.replaceAll('\r\n', '\n').split('\n')
  const blocks: string[] = []
  for (let index = 0; index < lines.length; index += 1) {
    const key = /^(\s*)(?:prefix|suffix):\s*\|-?\s*$/.exec(lines[index] ?? '')
    if (key === null || key[1] === undefined) continue
    const keyIndent = key[1].length
    const body: string[] = []
    let contentIndent = -1
    for (let cursor = index + 1; cursor < lines.length; cursor += 1) {
      const line = lines[cursor]
      if (line === undefined) break
      if (line.trim() === '') {
        body.push('')
        continue
      }
      const indent = line.length - line.trimStart().length
      if (indent <= keyIndent) break
      if (contentIndent === -1) contentIndent = indent
      body.push(line.slice(contentIndent))
    }
    blocks.push(body.join('\n').replace(/\n+$/, ''))
  }
  return blocks.join('')
}

describe('Agent Team shipping contract', () => {
  it('ships an opt-in Host patch and one explicit team-member preset', async () => {
    const [patch, manifestText] = await Promise.all([
      readFile(resolve(root, 'cordis.patch.yml'), 'utf8'),
      readFile(resolve(root, 'package.json'), 'utf8'),
    ])
    const preset = teamMemberPresetText(patch)
    expect(preset).toContain("name: '@deepseek-ai/dsh-agent-preset'")
    expect(patch).toContain('id: wowyuarm-agent-team-scope')
    expect(patch).toContain("name: '@deepseek-ai/dsh-agent-preset-registry'")
    expect(patch).toContain('default: team-member')
    expect(patch).toContain('id: wowyuarm-agent-team-preset-team-member')
    expect(patch).toContain('id: team-member')
    expect(patch).toContain('agentPresets: true')
    expect(patch).toContain("name: '@contexera/dsh-agent-team/host'")
    expect(patch).toContain("name: '@contexera/dsh-agent-team'")
    // The upstream registry row must stay gone: the Harness line after rc.2
    // removes `@deepseek-ai/dsh-invariants` wholesale, and the companion now
    // validates the ledger from its own fiber (src/invariant.ts).
    expect(patch).not.toContain("name: '@deepseek-ai/dsh-invariants'")
    expect(patch).toContain("name: '@contexera/dsh-agent-team/invariant'")
    // Team owns its SQLite backend and DomainFacility instead of changing
    // the Host's global storage-domain route. Bundle toggling must not
    // rebuild unrelated storage consumers.
    // Simulate the real layer stack because insert blocks append rather than
    // override; duplicate shipped ids would fail the boot sweep.
    expect(patch).not.toContain('sqlite-backend')
    expect(patch).not.toContain('storageDomain:')
    expect(patch).not.toContain('@deepseek-ai/dsh-storage-sqlite')
    const composed = applyEntryPatches([], [
      // rc.1 moved the storage rows from web-app into the base bundle; the
      // real layer stack is base → web-app → this bundle. The stack resolves
      // against the harness checkout this run was generated against, so a
      // certification round sweeps the CANDIDATE's rows, not the daily ones.
      ...loadOverlayPatches('shipping contract', resolve(root, `../${await shippedHarnessName()}/packages/bundle/base/cordis.patch.yml`)),
      ...loadOverlayPatches('shipping contract', resolve(root, `../${await shippedHarnessName()}/packages/bundle/web-app/cordis.patch.yml`)),
      ...loadOverlayPatches('shipping contract', resolve(root, 'cordis.patch.yml')),
    ], () => {})
    const ids = composed.map(entry => entry.id)
    expect(new Set(ids).size).toBe(ids.length)
    expect(composed.find(entry => entry.id === 'storage-domain')?.config).toEqual({ backend: 'json' })
    expect(patch).not.toContain('dsh-tool-agent-team')
    // The Human profile rides the Host row's own Config, and the settings
    // namespace IS that row's id: a form, a write, and the profile-document
    // patch all address it by the constant, so the two must not drift.
    // The row also has to stay the isolating group's nested row — a second
    // top-level row with this id duplicates it and fails the boot sweep.
    const scopeStart = patch.indexOf('    - id: wowyuarm-agent-team-scope')
    const scopeEnd = patch.indexOf('    - id: wowyuarm-agent-team-client')
    expect(scopeStart).toBeGreaterThanOrEqual(0)
    expect(scopeEnd).toBeGreaterThan(scopeStart)
    expect(patch.slice(scopeStart, scopeEnd)).toMatch(new RegExp(`^ {8}- id: ${HUMAN_PROFILE_SETTINGS_NAMESPACE}$`, 'm'))
    // The composition mounts it as that group's nested row, with no `config`
    // of its own: the schema defaults are the profile until the Human edits it.
    const scopeGroup = composed.find(entry => entry.id === 'wowyuarm-agent-team-scope')
    const nestedRows = (Array.isArray(scopeGroup?.config) ? scopeGroup.config : []) as { id?: string; name?: string; config?: unknown }[]
    const hostRow = nestedRows.find(entry => entry.id === HUMAN_PROFILE_SETTINGS_NAMESPACE)
    expect(hostRow?.name).toBe('@contexera/dsh-agent-team/host')
    expect(hostRow?.config).toBeUndefined()
    // Both fields must be volatile: rc.1 derives one settings form per ACTIVE
    // plugin instance from that instance's Config schema, and a non-volatile
    // field yields no form at all while a write to it throws. This is the
    // precondition of the derivation, asserted on the schema the Host ships.
    const profileFields = HUMAN_PROFILE_SETTINGS_SCHEMA.dict ?? {}
    expect(profileFields.name?.meta.volatile).toBe(true)
    expect(profileFields.avatarRef?.meta.volatile).toBe(true)
    // The row carries the profile, the wake-swap thresholds, and the hard
    // compaction boundary: the context engine's own knobs are gone, so a
    // deployment's stale `gate`/`jev` values pass through the non-strict
    // schema without becoming settings fields. Each threshold group is one
    // volatile node, so a write lands without a remount and the settings
    // service can derive it at all.
    const rowFields = TEAM_HOST_ROW_SETTINGS_SCHEMA.dict ?? {}
    expect(Object.keys(rowFields).sort()).toEqual(['avatarRef', 'memberCompaction', 'name', 'wakeRecycle'])
    expect(rowFields.wakeRecycle?.meta.volatile).toBe(true)
    expect(Object.keys(rowFields.wakeRecycle?.dict ?? {}).sort()).toEqual(['enabled', 'idleMs', 'minContextTokens'])
    expect(Object.values(rowFields.wakeRecycle?.dict ?? {}).every(child => child.meta.default !== undefined)).toBe(true)
    expect(rowFields.memberCompaction?.meta.volatile).toBe(true)
    expect(Object.keys(rowFields.memberCompaction?.dict ?? {}).sort()).toEqual(['enabled', 'tokens'])
    expect(Object.values(rowFields.memberCompaction?.dict ?? {}).every(child => child.meta.default !== undefined)).toBe(true)

    expect(preset).toContain("name: '@contexera/dsh-agent-team/tools'")
    expect(preset).toContain("name: '@deepseek-ai/dsh-agent-tool-presentation'")
    expect(preset).toContain('mode: native')
    expect(preset).toContain("name: '@contexera/dsh-agent-team/member-context'")
    expect(preset).toContain("name: '@deepseek-ai/dsh-command-compact'")
    // Every lib directory that can enter the pack must be cleaned, so a
    // deleted source module cannot leave stale output behind.
    const cleanScript = await readFile(resolve(root, 'scripts/clean-build-outputs.mjs'), 'utf8')
    const cleanTargets = [...cleanScript.matchAll(/['"](packages\/[^'"]+\/lib)['"]/g)].map(match => match[1])
    const shippedLibDirs = (JSON.parse(manifestText) as { files: string[] }).files
      .filter(pattern => pattern.startsWith('packages/') && pattern.endsWith('/lib/**/*'))
      .map(pattern => pattern.slice(0, -'/**/*'.length))
    expect(cleanTargets).toEqual(shippedLibDirs)
    const buildCommand = (JSON.parse(manifestText) as { scripts: { build: string } }).scripts.build
    expect(buildCommand.indexOf('npm run clean:build-outputs')).toBeGreaterThanOrEqual(0)
    expect(buildCommand.indexOf('npm run generate:typert')).toBeGreaterThan(buildCommand.indexOf('npm run clean:build-outputs'))
    for (const capability of [
      '@deepseek-ai/dsh-tool-bash', '@deepseek-ai/dsh-tool-pwsh', '@deepseek-ai/dsh-tool-fs',
      '@deepseek-ai/dsh-tool-fs-search', '@deepseek-ai/dsh-tool-jobs', '@deepseek-ai/dsh-tool-skill',
      '@deepseek-ai/dsh-tool-web',
    ]) expect(preset).toContain(`name: '${capability}'`)
    // Skills are per-Member (Host-mounted private-directory provider), so the
    // shared filesystem row is deliberately absent from the preset.
    expect(preset).not.toContain('@deepseek-ai/dsh-skill-filesystem')
    // Members plan through the ledger, so the session-local todo tool is
    // deliberately absent. The web bundle disables that row on the host plane,
    // which makes this preset's list the whole surface: removing the row really
    // removes the tool, and re-adding it should be a reviewed decision.
    expect(preset).not.toContain('@deepseek-ai/dsh-tool-todo')
    const bundleManifest = JSON.parse(manifestText) as {
      engines: { dsh?: string }
      peerDependencies: Record<string, string>
      exports: Record<string, { default?: string }>
      dsh: { client: { platform: string; inject: string[] } }
    }
    // A plugin's own `engines.dsh` decides DSH compatibility alone (peers are
    // then ignored), so it states the same certified line the peers do: one
    // line, one answer whichever field an installer reads.
    expect(bundleManifest.engines.dsh).toBe('>=0.2.1-rc.2 <0.2.2')
    expect(bundleManifest.peerDependencies['@deepseek-ai/dsh-tool-web']).toBe('>=0.2.1-rc.2 <0.2.2')
    expect(bundleManifest.peerDependencies['@deepseek-ai/dsh-command-compact']).toBe('>=0.2.1-rc.2 <0.2.2')
    expect(bundleManifest.peerDependencies['@deepseek-ai/dsh-agent-preset']).toBe('>=0.2.1-rc.2 <0.2.2')
    expect(bundleManifest.peerDependencies['@deepseek-ai/dsh-agent-preset-registry']).toBe('>=0.2.1-rc.2 <0.2.2')
    expect(bundleManifest.peerDependencies['@deepseek-ai/dsh-agent-presets']).toBeUndefined()
    // The certified baseline moves as one cut: every DSH peer carries the same
    // range, or an install resolves two DSH generations at once. No host-scope
    // package may sit in `dependencies` (see the host-scope gate below).
    expect([...dshPeerRanges(bundleManifest)]).toEqual(['>=0.2.1-rc.2 <0.2.2'])
    expect(preset).toContain('compaction: true')
    expect(preset).toContain('toolResultPruner: true')
    expect(preset).toContain('team_inbox, team_thread, team_attention, team_message, team_dm, team_task, and team_view')
    expect(preset).toContain('from a fully drained team_thread read, your own committed mutation, or a complete Thread rejection that provides one')
    expect(preset).toContain('A rejection is not a commit')
    expect(preset).toContain('only read does that')
    expect(preset).not.toContain('a rejection supplies no write basis')
    expect(preset).toContain('reply in plain text')
    expect(preset).toContain('not a reply channel for it')
    expect(preset).toContain('Lead with the conclusion or state; put mechanical detail')
    expect(preset).toContain('never drop detail a peer Member needs, move it below')
    expect(preset).toContain('mention the Human as @human — that is how they are notified')
    expect(preset).toContain('what needs deciding and what happens by default')
    // Autonomy is the default and the escalation bar is a closed list. The
    // 2026-10-05 ledger scan is why these lines exist: 836 of 1,502 Member
    // messages mentioned the Human, 51% drew an immediate reply, and the
    // median reply was 29 characters ("可以", "合吧", "分支删了吧") — the
    // Human was rubber-stamping work the Member already had grounds to
    // settle, and in 17% of replies was merely routing to another Member.
    // Each assertion below pins one of the three behaviours that scan found
    // missing; deleting one silently restores the escalation habit.
    expect(preset).toContain('Decide and act by default')
    expect(preset).toContain('Never close a message with a question whose answer you could determine yourself')
    expect(preset).toContain('Mention the Human only when one of these holds')
    expect(preset).toContain('A finished piece of work is reported, not submitted for approval')
    expect(preset).toContain('The Human is not a router')
    // Progress chatter is opt-in: an expected step earns no message, and a
    // taken Task is announced without waiting for anyone to bless the plan.
    expect(preset).toContain('Do not wait for anyone to confirm the plan')
    expect(preset).toContain('silence while working is normal and correct')
    // Disagreement resolves inside the team by function ownership (operator
