83	function isSurfaceActivityBinding(value: unknown): value is SurfaceActivityBinding {
84	  if (typeof value !== 'object' || value === null) return false
85	  const item = value as { readonly scope?: unknown; readonly activityRef?: unknown; readonly threadRef?: unknown; readonly projectRef?: unknown; readonly factDigest?: unknown }
86	  if (typeof item.activityRef !== 'string' || typeof item.factDigest !== 'string') return false
87	  return (item.scope === 'thread' && typeof item.threadRef === 'string' && item.projectRef === undefined)
88	    || (item.scope === 'main' && typeof item.projectRef === 'string' && item.threadRef === undefined)
89	}
