108	/** A Command or Remote projection is not a Session output: only the bound activity text attests. */
109	export function isActivityOnSurface(entries: readonly TeamMessageSurface[], fact: ActivityFact): boolean {
110	  const identity = activityIdentity(fact)
111	  const factDigest = activityFactDigest(fact)
112	  return entries.some(entry => entry.activities.some(activity => activity.factDigest === factDigest
