it('reads with the conservative capacity when the model reports an unusable context window', async () => {
  const { ctx, adapter, agent, workspaceId, projectRef, post, call } = await mainStream()
  // Unusable metadata must not fail a read that does not need the window: the
  // read falls back to the conservative limit instead of refusing.
  adapter.resolveModelWindow = () => 0
  const short = await post('Ordinary update.')
  const result = await call('read')
  expect(result).toContain('acknowledged 1 unread update(s)')
  expect(result).not.toContain('exceeds the reading capacity')
